import type { NativePlatform } from '@expo/config';
import type { ServerRequest } from './server.types';
/** Supported native runtime platforms. */
export type RuntimePlatform = NativePlatform;
/**
 * Extract the runtime platform from the server request.
 * 1. Query param `platform`: `?platform=ios`
 * 2. Header `expo-platform`: `'expo-platform': ios`
 * 3. Legacy header `exponent-platform`: `'exponent-platform': ios`
 *
 * Returns first item in the case of an array.
 */
export declare function parsePlatformHeader(req: ServerRequest): string | null;
/** Guess the platform from the user-agent header. */
export declare function resolvePlatformFromUserAgentHeader(req: ServerRequest): string | null;
/** Assert if the runtime platform is not included. */
export declare function assertMissingRuntimePlatform(platform?: any): asserts platform;
/** Assert if the runtime platform is not correct. */
export declare function assertRuntimePlatform(platform: string): asserts platform is RuntimePlatform;
